# -*- coding: utf-8 -*-
import io, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from rowlib import panel_span
SK='sketchy.html'; s=io.open(SK,encoding='utf-8').read()
assert "id:'s16p01c'" not in s
i,j=panel_span(s,'s16p01b')
P = """,
 {id:'s16p01c',t:"손님이 오기 전 — 닫히고, 뒤틀리고, 도로 뒤집는다",br:"같은 벽을 <b>아무도 접수받지 않는 때</b>로 한 번 더 그렸다. 문 달린 창구는 <b>덧문이 닫히고 자물쇠가 걸렸고</b>, 창구 일곱 가운데 <b>다섯이 벽돌</b>이다. 손님 넷이 저마다 <b>다른 물건 하나씩</b>을 들고 줄을 섰고, 손이 얹힌 창구 <b>하나만 틀이 뒤틀렸다</b>. 오른쪽 끝에서는 주자가 주저앉아 <b>토큰을 도로 뒤집었다</b>.",bx:`<p><b>덱이 오래 켜는 것만 그렸다.</b> 앞 두 판은 <b>열리고 · 흐르고 · 달리고 · 찍는</b> 장면뿐이었다. 이 판은 <b>그 반대쪽</b>이다 — 오기 전과 간 뒤, 닫힘과 꺼짐.</p><p><b>닫힌 통로.</b> 문이 달린 창구(이온통로 수용체)의 <b>덧문이 닫히고 자물쇠가 걸려</b> 있다. 리간드가 붙기 전 통로의 상태가 <b>닫힘</b>이라는 것이 이 한 장면이다. ⚠ <b>벽돌로 막힌 창구</b>와 헷갈리면 안 된다 — 벽돌은 GPCR 이고 「이온 구멍이 아예 없다」는 뜻이지 「지금 닫혀 있다」가 아니다. <b>닫힌 것은 열릴 수 있고, 벽돌은 안 열린다.</b></p><p><b>수를 세면 GPCR 이 압도한다.</b> 창구 일곱 가운데 <b>다섯이 벽돌</b>이고 문 달린 것과 넓은 것은 하나씩뿐이다. 사람 세포막 수용체 가운데 <b>가장 종류가 많은 것이 GPCR</b>이라는 것이 그 셈이다.</p><p><b>틀이 뒤틀린 창구 하나.</b> 다른 창틀은 다 반듯한데 <b>손이 얹힌 창구 하나만</b> 네모가 일그러져 있다. 리간드가 붙어서 수용체에 일어나는 <b>직접</b> 변화가 그것이다 — <b>모양이 바뀐다</b>. 그다음 일(이온이 흐르든 주자가 달리든 도장을 찍든)은 전부 <b>이 변화의 결과</b>다.</p><p><b>손에 든 것이 이름이다.</b> <b>열린 담뱃갑</b>은 니코틴성 아세틸콜린이고 <b>문 달린 창구</b> 앞에 섰다. <b>로프가 걸린 도르래</b>는 로돕신(빛)이고, <b>뚜껑이 터진 드럼통</b>은 에피네프린이다 — 둘 다 <b>벽돌 창구</b> 앞이다. <b>화분에 심긴 묘목</b>은 생장인자이고 <b>둘이 서는 넓은 창구</b> 앞이다.</p><p><b>주자가 스스로 끈다.</b> 오른쪽 끝에서 주자가 주저앉아 <b>토큰을 도로 뒤집어</b> 무릎에 놓았다. GPCR 경로를 끄는 <b>첫째 기작</b>이 이것이다 — G단백질이 <b>제 손으로</b> GTP 를 가수분해해 GDP 로 돌린다. ★ 끄는 사람이 따로 오는 것이 아니라 <b>달리던 그 사람이 스스로</b> 멈춘다.</p><span class='q'><b>여기서 갈리는 문제.</b> 「리간드 결합 전 이온통로의 상태는?」(<b>닫힘</b>) · 「리간드 결합이 수용체에 일으키는 직접 변화는?」(<b>입체구조 변화</b>) · 「세포표면 수용체 중 가장 많은 종류는?」(<b>GPCR</b>) · 「GPCR 신호를 끄는 1차 기작은?」(<b>G단백질의 GTP 가수분해</b>) · 「세 수용체의 대표 리간드는?」(<b>담뱃갑·도르래와 드럼·묘목</b>).</span>`,f:[["문이 달린 창구의 <b>덧문이 닫히고</b> 작은 <b>자물쇠</b>가 걸렸다 — 그 앞에 <b>열린 담뱃갑</b>을 든 손님이 서 있는데 아직 아무도 열어 주지 않았다","리간드가 붙기 <b>전</b> 이온통로의 상태는 <b>닫힘</b>이다. ⚠ <b>벽돌로 막힌 창구</b>와 헷갈리면 안 된다 — 벽돌은 GPCR 이고 「이온 구멍이 <b>아예 없다</b>」는 뜻이다. <b>닫힌 것은 열릴 수 있고 벽돌은 안 열린다</b>",["B0-68"]],
  ["벽에 창구가 <b>일곱</b>인데 그중 <b>다섯이 벽돌</b>이고, 문 달린 것과 넓은 것은 <b>하나씩</b>뿐이다","사람 세포막 수용체 가운데 <b>가장 종류가 많은 것이 G단백질 결합 수용체(GPCR)</b>다. ★ 셈이 그대로 답이다 — 벽돌 창구가 나머지를 압도한다",["B0-28"]],
  ["창틀이 다 반듯한데 <b>손이 얹힌 창구 하나만</b> 네모가 <b>일그러져</b> 있다","리간드가 붙어 수용체에 일어나는 <b>직접</b> 변화는 <b>입체구조(형태) 변화</b>다. ★ 그다음 일 — 이온이 흐르든 주자가 달리든 도장을 찍든 — 은 전부 <b>이 변화의 결과</b>다",["B0-25"]],
  ["손님 넷이 저마다 <b>다른 물건 하나씩</b>을 들었다 — <b>열린 담뱃갑</b> · <b>로프가 걸린 도르래</b> · <b>뚜껑이 터진 드럼통</b> · <b>화분에 심긴 묘목</b> · 그리고 저마다 <b>다른 창구</b> 앞에 섰다","세 수용체의 대표 리간드다 — 이온통로 수용체는 <b>니코틴성 아세틸콜린</b>(담뱃갑, 문 달린 창구), GPCR 은 <b>빛(로돕신)</b>과 <b>에피네프린</b>(도르래와 드럼통, 벽돌 창구), RTK 는 <b>생장인자</b>(묘목, 넓은 창구)다. ★ GPCR 앞에만 <b>둘</b>이 선 것이 요점이다",["S-SG-1"]],
  ["오른쪽 끝, 벽에서 떨어져 <b>주저앉은 주자</b>가 <b>토큰을 도로 뒤집어</b> 무릎에 놓았다 · 또 하나는 바닥에 <b>엎어져</b> 있다","GPCR 경로를 끄는 <b>1차 기작</b> — G단백질이 <b>제 손으로 GTP 를 가수분해</b>해 GDP 로 돌린다. ★ 끄는 사람이 따로 오는 것이 아니라 <b>달리던 그 사람이 스스로</b> 멈춘다",["B0-52"]],
  ["★ 같은 벽인데 <b>아무도 접수받지 않는다</b> — 앞의 두 판은 열리고 흐르고 달리고 찍는 장면뿐이었다","<b>켜는 것만 외우면 반쪽이다.</b> 이 판이 그 반대쪽을 모아 놓았다 — <b>오기 전</b>(닫힌 문) · <b>붙는 순간</b>(뒤틀린 틀) · <b>간 뒤</b>(도로 뒤집힌 토큰)"]]}"""
s2=s[:j+1]+P+s[j+1:]
io.open(SK,'w',encoding='utf-8').write(s2)
print('inserted',len(s2)-len(s))
